local config = {
  ui_story_31290401_1_dialog_content = "Kita sudah sampai!",
  ui_story_31290401_2_dialog_content = "Ini pasar, ya? Sepertinya ramai juga!",
  ui_story_31290401_3_dialog_content = "Benar! Hari ini ada <color=#FFB400>Bartering Day</color> untuk White Flame Mercenaries!",
  ui_story_31290401_4_dialog_content = "<color=#FFB400>Bartering Day</color>?",
  ui_story_31290401_5_dialog_content = "Intinya, orang-orang boleh datang kemari untuk <color=#FFB400>saling bertukar barang</color>.",
  ui_story_31290401_6_dialog_content = "Di sini, nilai barang ditentukan oleh orang-orang yang terlibat dalam pertukaran, bukan berdasar harga Nightium.",
  ui_story_31290401_7_dialog_content = "Di pasar ini, sebuah lukisan bunga bisa saja senilai dengan sekeping koin tembaga dari peradaban yang telah musnah!",
  ui_story_31290401_8_dialog_content = "Kita boleh mengajukan penawaran asalkan orang yang kita ajak barter bersedia melakukan pertukaran!",
  ui_story_31290401_9_dialog_content = "Kedengarannya sangat mengasyikkan!",
  ui_story_31290401_10_dialog_content = "Tapi... bukankah ada risiko orang yang kurang teliti menawarkan barang murah untuk ditukar dengan barang yang jauh lebih mahal?",
  ui_story_31290401_11_dialog_content = "Yah, selama pemilik barang tersebut menyetujui pertukarannya, tak ada peraturan lain untuk dipertimbangkan.",
  ui_story_31290401_12_dialog_content = "Kecuali, tentu saja, kalau orang itu berniat cari untung.",
  ui_story_31290401_13_dialog_content = "\"Cari untung\"... Maksudmu, bertukar barang di sini, lalu menjualnya dengan harga Nightium di luar pasar?",
  ui_story_31290401_14_dialog_content = "Tepat sekali. Jika sudah melibatkan uang, makna Bartering Day akan berubah drastis.",
  ui_story_31290401_15_dialog_content = "Tapi, bukankah yang seperti itu tak bisa dihindari?",
  ui_story_31290401_16_dialog_content = "Benar, tapi siapa pun yang melakukannya tak akan dianggap lagi sebagai anggota White Flame Mercenaries, dan akan diusir dari Umbraton.",
  ui_story_31290401_17_dialog_content = "Mereka akan jadi target buruan dalam sayembara tentara bayaran, hingga akhirnya mereka meninggalkan kota.",
  ui_story_31290401_18_dialog_content = "(Ini terdengar seperti... Hal yang akan dilakukan kelompok tentara bayaran, sih...)",
  ui_story_31290401_19_dialog_content = "Kamu lihat orang itu? Dia adalah pelukis andal. Dulu aku pernah bertukar karya dengannya.",
  ui_story_31290401_20_dialog_content = "Commander Luke! Commander Luke! Ada tugas baru untukmu!",
  ui_story_31290401_21_dialog_content = "Maaf, PlayerName. Sepertinya ada urusan yang harus kutangani di sana.",
  ui_story_31290401_22_dialog_content = "Kamu tak apa-apa kalau sendirian, 'kan? Apa perlu kuutus seseorang untuk menemanimu?",
  ui_story_31290401_23_dialog_content = "Hah? T-tidak usah. Aku akan baik-baik saja, jangan khawatir!",
  ui_story_31290401_24_dialog_content = "Baiklah, kalau begitu silakan melihat-lihat. Aku akan kembali setelah urusanku selesai.",
  ui_story_31290401_25_dialog_content = "Tugas baru saat ada Bartering Day? Luke memang sibuk... Ya sudah, aku akan melihat-lihat saja sekarang.",
  ui_story_31290401_26_dialog_content = "Ramai sekali pasar ini! Ada gerobak camilan, stan lukis, dan bahkan butik perhiasan...",
  ui_story_31290401_27_dialog_content = "Ada yang menjual kupu-kupu juga di sini!",
  ui_story_31290401_28_dialog_content = "(Wah! Itu orangnya!)",
  ui_story_31290401_29_dialog_content = "(Tadi Commander Luke mendampinginya secara pribadi... Nah, aku yakin ini akan berhasil!)",
  ui_story_31290401_30_dialog_content = "Hei, kamu! Iya, kamu! Yang pakai ikat kepala warna hitam-putih!",
  ui_story_31290401_31_dialog_content = "... Kok diam saja, sih? Mungkin harus lebih dekat...",
  ui_story_31290401_32_dialog_content = "<size=45>Hei, kamu! Yang pakai ikat kepala warna hitam-putih!!</size>",
  ui_story_31290401_33_dialog_content = "Sialan, dia pasti tidak mendengarku gara-gara suara bising ini! Kalau begitu, biar kucoba... begini!",
  ui_story_31290401_34_dialog_content = "<size=50>Aduh!!!</size>",
  ui_story_31290401_35_dialog_content = "<size=50>Bokongku!!!</size>",
  ui_story_31290401_36_dialog_content = "Siapa itu?! Siapa yang melempari bokongku?!",
  ui_story_31290401_37_dialog_content = "(... Hah? Orang itu melambai kepadaku?)",
  ui_story_31290401_38_dialog_content = "(Sepertinya dia memintaku pergi ke sana... Apa dia lihat orang yang menyerangku barusan?!)",
  ui_story_31290401_39_dialog_content = "Halo! Anu... Tadi kamu melambai kepadaku?",
  ui_story_31290401_40_dialog_content = "Benar sekali! Maaf untuk yang tadi, kawan... Aku yang melempar batu ke arahmu barusan.",
  ui_story_31290401_41_dialog_content = "Tapi, aku tak punya... pilihan lain!",
  ui_story_31290401_42_dialog_content = "Aku mencoba memanggilmu berkali-kali, tapi kamu tidak mendengarnya... Aku butuh bantuanmu!",
  ui_story_31290401_43_dialog_content = "Oh... S-sebentar, kau mengenalku?",
  ui_story_31290401_44_dialog_content = "Minta tolong apa tepatnya?",
  ui_story_31290401_45_dialog_content = "Selain itu, apa tak ada cara lain untuk minta bantuan selain melempar batu?!",
  ui_story_31290401_46_dialog_content = "... Masih sakit, ya? Maafkan aku... Mau kuelus-elus?",
  ui_story_31290401_47_dialog_content = "Elus-elus?! Katakan saja apa maumu!!",
  ui_story_31290401_48_dialog_content = "Eh... Baiklah. Aku akan menebus kesalahanku setelah menjelaskannya!",
  ui_story_31290401_49_dialog_content = "Begini, tadi aku melihatmu datang kemari dengan Commander Luke... Kalian berdua pasti cukup akrab, 'kan?",
  ui_story_31290401_50_dialog_content = "Ya, Luke memang temanku.",
  ui_story_31290401_51_dialog_content = "Apa ada hubungannya dengan dia?",
  ui_story_31290401_52_dialog_content = "Iya!",
  ui_story_31290401_53_dialog_content = "Belakangan ini Commander Luke sangat berdedikasi.",
  ui_story_31290401_54_dialog_content = "Bukan, berdedikasi bukan kata yang tepat... Sepertinya terobsesi atau kerasukan justru lebih pas.",
  ui_story_31290401_55_dialog_content = "Dia benar-benar sudah gila kerja... Terutama hari ini!",
  ui_story_31290401_56_dialog_content = "Hari ini? Kenapa begitu?",
  ui_story_31290401_57_dialog_content = "Ini karena...",
  ui_story_31290401_58_dialog_content = "Begini saja, aku mau tanya. Apa kamu tahu siapa commander lama?",
  ui_story_31290401_59_option_content = "Ya, aku tahu.",
  ui_story_31290401_60_dialog_content = "Commander lama adalah ayah angkat Luke, yang sekaligus mantan pemimpin White Flame Mercenaries.",
  ui_story_31290401_61_dialog_content = "Heh, rupanya hubungan kalian lebih dekat dari perkiraanku!",
  ui_story_31290401_62_option_content = "Tidak juga...",
  ui_story_31290401_63_dialog_content = "Commander lama adalah ayah angkat Luke, serta mantan pemimpin White Flame Mercenaries.",
  ui_story_31290401_64_dialog_content = "Setelah dia wafat, Luke mengambil alih komando White Flame Mercenaries.",
  ui_story_31290401_65_dialog_content = "Hubungan mereka sangat dekat.",
  ui_story_31290401_66_dialog_content = "Begitu, ya...",
  ui_story_31290401_67_dialog_content = "Karena Commander Luke sangat suka serangga, ada banyak pameran serangga dan bahkan rumah kaca di Bartering Day yang sebelum-sebelumnya.",
  ui_story_31290401_68_dialog_content = "Selain itu, ada kuliah singkat tentang serangga yang dibawakan oleh Commander Luke untuk berbagi pengetahuannya dengan semua orang!",
  ui_story_31290401_69_dialog_content = "Commander lama suka menyimak kuliahnya meskipun tidak memahami penjelasannya sama sekali.",
  ui_story_31290401_70_dialog_content = "Rumah kaca... untuk serangga? Memangnya serangga butuh akomodasi spesial?",
  ui_story_31290401_71_dialog_content = "Barusan aku melihat kupu-kupu... tapi mereka tidak ditempatkan di ruangan apa pun.",
  ui_story_31290401_72_dialog_content = "Jangan-jangan...",
  ui_story_31290401_73_dialog_content = "Seluruh pasar ini sepenuhnya dikendalikan oleh iklim?!",
  ui_story_31290401_74_dialog_content = "B-bukan seperti itu! Kami hanya <color=#FFB400>mengubah tanggal</color> Bartering Day, itu saja.",
  ui_story_31290401_75_dialog_content = "Mengubah tanggal? ... Kupikir masuk akal juga.",
  ui_story_31290401_76_dialog_content = "Dulu Bartering Day tidak diadakan di tanggal ini.",
  ui_story_31290401_77_dialog_content = "Penggantian tanggal itu adalah ide commander lama.",
  ui_story_31290401_78_dialog_content = "Setelah insiden tahun '88, commander lama hampir tidak pernah beranjak dari ranjangnya.",
  ui_story_31290401_79_dialog_content = "Dua tahun lalu, tiba-tiba penyakitnya memburuk...",
  ui_story_31290401_80_dialog_content = "Setelah itu, dia merasa ajalnya akan segera tiba.",
  ui_story_31290401_81_dialog_content = "Kemudian dia meminta letnan Commander Luke...",
  ui_story_31290401_82_dialog_content = "Untuk mengganti tanggal Bartering Day tahunan White Flame Mercenaries dengan tanggal kematiannya.",
  ui_story_31290401_83_dialog_content = "S-sebentar... Jadi, maksudmu hari ini sebenarnya adalah... <color=#FFB400>hari kematian</color> commander lama?!",
  ui_story_31290401_84_dialog_content = "Tapi, kenapa?",
  ui_story_31290401_85_dialog_content = "Lihat saja ke sekeliling...",
  ui_story_31290401_86_dialog_content = "Bartering Day terlihat seperti acara yang meriah, dan semua orang tampak sangat sibuk.",
  ui_story_31290401_87_dialog_content = "Benar sekali! Semua orang dari segala kalangan jauh lebih sibuk saat Bartering Day.",
  ui_story_31290401_88_dialog_content = "Menyiapkan lokasi, melakukan pemeriksaan, dan mengendalikan alur barang selama acara...",
  ui_story_31290401_89_dialog_content = "Bahkan kami mengundang pembicara tamu dari Istvan Gang untuk membagikan keahlian pengelolaan hari ini!",
  ui_story_31290401_90_dialog_content = "Nah, kalau tetap sibuk seperti ini sepanjang hari...",
  ui_story_31290401_91_dialog_content = "Kami tak akan sempat merindukan rekan-rekan yang telah gugur.",
  ui_story_31290401_92_dialog_content = "Menurutku... commander lama pasti tak ingin kalian berduka hari ini.",
  ui_story_31290401_93_dialog_content = "Benar.",
  ui_story_31290401_94_dialog_content = "Untuk menghormati permintaannya, kami berusaha tetap sibuk agar tidak sedih...",
  ui_story_31290401_95_dialog_content = "Tapi, meski begitu Commander Luke akan bekerja mati-matian.",
  ui_story_31290401_96_dialog_content = "Saking sibuknya bekerja, dia sampai tidak tidur dan makan.",
  ui_story_31290401_97_dialog_content = "Belakangan ini dia batuk-batuk hebat, dan tidak nafsu makan...",
  ui_story_31290401_98_dialog_content = "Dia selalu berkata, \"Sepertinya ada pekerjaan lain,\" atau \"Saatnya mengorek lebih banyak informasi di jalanan...\"",
  ui_story_31290401_99_dialog_content = "Hari ini juga sama walaupun kami sudah membantunya menyelesaikan persiapan untuk Bartering Day sejak jauh-jauh hari.",
  ui_story_31290401_100_dialog_content = "Meski begitu, dia tetap tak mau berhenti barang sejenak pun, dan justru mencari lebih banyak pekerjaan.",
  ui_story_31290401_101_dialog_content = "Kami khawatir... dia masih berduka atas kepergian commander lama.",
  ui_story_31290401_102_dialog_content = "Sampai-sampai dia tak mau bersantai atau istirahat sedikit pun.",
  ui_story_31290401_103_dialog_content = "Aku mengerti.",
  ui_story_31290401_104_dialog_content = "Jadi, ini pasti...",
  ui_story_31290401_105_dialog_content = "Alasanmu meminta bantuanku? Baiklah, kawan.",
  ui_story_31290401_106_dialog_content = "Jika kamu bisa membantu menghibur commander, kami akan sangat menghargainya. Kami tidak mau dia terus bekerja tanpa menjaga kesehatannya.",
  ui_story_31290401_107_dialog_content = "Bagi kami, kesehatannya jauh lebih penting dari kejayaan White Flame Mercenaries.",
  ui_story_31290401_108_dialog_content = "Tapi, setiap kali kami memintanya untuk bersantai, dia akan menjawab... \"Iya, iya, aku tahu...\"",
  ui_story_31290401_109_dialog_content = "Lalu dia terus bekerja seperti biasa... Mungkin dia memang masih berduka.",
  ui_story_31290401_110_dialog_content = "*Berdesah* Meski sangat memedulikan kami, dia tak mau mendengar setiap kami membahas masalah ini. Aku tahu itu.",
  ui_story_31290401_111_dialog_content = "Bagaimanapun juga, kami sudah kehilangan satu commander...",
  ui_story_31290401_112_dialog_content = "Akan kucoba membantu kalian semampuku. Aku janji.",
  ui_story_31290401_113_dialog_content = "Eh, sejujurnya... aku tak bisa menjamin semuanya akan berubah...",
  ui_story_31290401_114_dialog_content = "Tapi, aku akan tetap berusaha!",
  ui_story_31290401_115_dialog_content = "A-aku... sangat berterima kasih!",
  ui_story_31290401_116_dialog_content = "Eh? Itu dia, 'kan? Sepertinya dia sudah kembali!",
  ui_story_31290401_117_dialog_content = "Pekerjaannya sudah selesai?",
  ui_story_31290401_118_dialog_content = "Ya, memang dia! Kalau begitu, kuserahkan padamu! Kami tak akan mengganggu!",
  ui_story_31290401_X118_dialog_content = "Aku masih harus mengambil batu yang kulempar tadi!",
  ui_story_31290401_X119_dialog_content = "Jangan dibahas lagi!!",
  ui_story_31290401_119_dialog_content = "Ehehe... Maaf! Berjuanglah, kawan kecil! Kami mengandalkanmu!",
  ui_story_31290401_120_dialog_content = "Dia... buru-buru pergi...",
  ui_story_31290401_121_dialog_content = "Maafkan aku, PlayerName. Tadi tiba-tiba ada tugas, tapi semua sudah beres, kok.",
  ui_story_31290401_122_dialog_content = "Barusan kulihat kamu bicara dengan salah satu kaptenku. Apa dia bisa menjelaskan lebih banyak tentang White Flame Mercenaries?",
  ui_story_31290401_123_dialog_content = "Iya... Dia memberi penjelasan panjang lebar tentang kalian dan sejarah guild ini.",
  ui_story_31290401_124_dialog_content = "Baguslah...",
  ui_story_31290401_125_dialog_content = "Luke... Apa kamu masih bersedih atas wafatnya commander lama?",
  ui_story_31290401_126_dialog_content = "Hah...? Commander lama?",
  ui_story_31290401_X126_dialog_content = "... Begitu rupanya. Dia benar-benar memberi penjelasan mendetail tentang sejarah kami.",
  ui_story_31290401_127_dialog_content = "PlayerName...",
  ui_story_31290401_128_dialog_content = "Kalau kubilang aku sudah tidak bersedih atas kepergiannya, berarti aku bohong.",
  ui_story_31290401_129_dialog_content = "Tapi, kupikir aku sudah menerima kepergiannya seperti yang dia harapkan.",
  ui_story_31290401_130_dialog_content = "... Sungguh?",
  ui_story_31290401_131_dialog_content = "Iya. Aku bukan orang yang terjebak di masa lalu dan berhenti bergerak maju. Itu bukan sesuatu yang orang dewasa akan lakukan.",
  ui_story_31290401_132_dialog_content = "Bagiku, cara terbaik untuk menghormati harapan commander lama adalah dengan bekerja sepenuh hati.",
  ui_story_31290401_133_dialog_content = "Jadi... Itu alasanmu bekerja keras tanpa henti akhir-akhir ini?",
  ui_story_31290401_134_dialog_content = "Tentu saja, itu juga demi kemajuan White Flame Mercenaries dan kehidupan yang lebih baik untuk mereka.",
  ui_story_31290401_135_dialog_content = "Tapi... Tadi kaptenmu bilang, kamu masih berduka atas kepergian commander lama.",
  ui_story_31290401_136_dialog_content = "Hah? Dia juga...? Begitukah pendapat semua orang?",
  ui_story_31290401_137_dialog_content = "Dia bilang mereka sudah memintamu untuk istirahat, tapi kamu tidak peduli dan terus bekerja tanpa henti.",
  ui_story_31290401_138_dialog_content = "Selain itu, mereka juga mulai mencemaskan kesehatanmu.",
  ui_story_31290401_139_dialog_content = "Kesehatanku? Maksudnya... karena aku batuk-batuk?",
  ui_story_31290401_140_dialog_content = "Belakangan ini aku sudah mengendalikan kebiasaan makanku, tapi tenggorokanku jadi gatal gara-gara makanan kering.",
  ui_story_31290401_141_dialog_content = "Nah, soal bekerja tanpa henti, sudah kubilang pada mereka bahwa...",
  ui_story_31290401_142_dialog_content = "... Sekarang aku paham.",
  ui_story_31290401_143_dialog_content = "Sepertinya ada masalah komunikasi.",
  ui_story_31290401_144_dialog_content = "Saking sibuknya menyelesaikan tugas, aku jadi tak sempat membicarakan hal lain selain pekerjaan...",
  ui_story_31290401_145_dialog_content = "Memang sudah lama sekali aku tidak bicara dari hati ke hati dengan mereka.",
  ui_story_31290401_146_dialog_content = "Tidak bisa dibayangkan seorang commander melakukan kesalahan semacam ini...",
  ui_story_31290401_147_dialog_content = "Sepertinya masih ada satu hal lagi yang harus commander lama ajarkan.",
  ui_story_31290401_148_dialog_content = "Aku memang kurang berinteraksi dengan anak buahku.",
  ui_story_31290401_149_dialog_content = "Aku perlu meluangkan waktu untuk bicara dengan mereka... Dan bukannya sibuk bekerja.",
  ui_story_31290401_150_dialog_content = "Mereka benar-benar peduli padamu, Luke.",
  ui_story_31290401_151_dialog_content = "Aku tahu. Aku janji akan berbicara dengan mereka nanti malam.",
  ui_story_31290401_152_dialog_content = "Bagaimanapun, mereka bukan hanya rekan seperjuangan... tapi juga keluargaku.",
  ui_story_31290401_153_dialog_content = "Nah, kalau begitu pekerjaanku di sini sudah selesai!",
  ui_story_31290401_154_dialog_content = "Hah! Terima kasih, PlayerName.",
  ui_story_31290401_155_dialog_content = "Oh, iya, aku harus minta maaf lagi. Sepertinya hari ini kunjunganmu kemari tidak begitu menyenangkan.",
  ui_story_31290401_156_dialog_content = "... Ambillah batu serangga lukis ini sebagai permintaan maafku.",
  ui_story_31290401_157_dialog_content = "Batu serangga lukis?",
  ui_story_31290401_158_dialog_content = "Hah...? Hei! Batu ini...",
  ui_story_31290401_159_dialog_content = "Ah! Ini 'kan batu yang tadi!!",
  ui_story_31290401_160_dialog_content = "Bukankah ini batu yang mengenai bokongku tadi?!",
  ui_story_31290401_161_dialog_content = "Hmm? Apa maksudmu? Biasanya aku memberikan batu serangga lukis kepada orang lain sebagai ucapan terima kasih.",
  ui_story_31290401_162_dialog_content = "Apa hubungannya dengan mengenai bokong?",
  ui_story_31290401_163_dialog_content = "Anu... begitulah cara kaptenmu memanggilku tadi.",
  ui_story_31290401_164_dialog_content = "Omong-omong, sebaiknya kamu siap-siap bicara dengan kapten dan yang lainnya...",
  ui_story_31290401_165_dialog_content = "Oh, iya, tolong ingatkan dia bahwa... melempar batu untuk minta bantuan itu tidak baik!!!",
  ui_story_31290601_1_dialog_content = "Ini adalah <color=#FFB400>Flapper hujan</color>, binatang ajaib yang terancam punah.",
  ui_story_31290601_2_dialog_content = "Mereka hidup di hutan yang panas dan lembab.",
  ui_story_31290601_3_dialog_content = "Sayap besar mereka memberi mereka kemampuan untuk terbang melalui hutan seperti hantu.",
  ui_story_31290601_4_dialog_content = "Pola di sayap mereka datang dan pergi, seperti hujan.",
  ui_story_31290601_5_dialog_content = "Ketika mereka mengepakkan sayapnya, pola-pola biasa terhubung.",
  ui_story_31290601_6_dialog_content = "Dan mereka terlihat seperti pelangi terbang.",
  ui_story_31290601_7_dialog_content = "Kita bisa saja melihat salah satunya membumbung tinggi di langit...",
  ui_story_31290601_8_dialog_content = "Tapi itu dipaku ke kotak sekarang.",
  ui_story_31290601_9_dialog_content = "<color=#e8d9bb>Jauh di dalam hutan</color>",
  ui_story_31290601_10_dialog_content = "Awas, PlayerName!",
  ui_story_31290601_11_dialog_content = "<color=#e8d9bb>Duar!!!</color>",
  ui_story_31290601_12_dialog_content = "Terima kasih, Lukas.",
  ui_story_31290601_13_dialog_content = "Jangan khawatir, lakukan saja pekerjaanku.",
  ui_story_31290601_14_dialog_content = "Aku tidak percaya dia berhasil menembus Eclipsites.",
  ui_story_31290601_15_dialog_content = "Pemburu ini lebih brutal dari yang saya kira, dan bahkan untuk mereka sendiri!",
  ui_story_31290601_16_dialog_content = "Mereka tahu hutan seperti punggung tangan mereka. Mereka telah memasang perangkap di mana Eclipsites berada.",
  ui_story_31290601_17_dialog_content = "Dan mereka meninggalkan ini <color=#FFB400>tanda-tanda bertahan hidup</color>.",
  ui_story_31290601_18_dialog_content = "Lihatlah kaleng-kaleng yang dibuang dan kayu yang terbakar... Semua untuk mengalihkan perhatian.",
  ui_story_31290601_19_dialog_content = "Tidak heran guild tidak tahu apa yang harus dilakukan tentang mereka.",
  ui_story_31290601_20_dialog_content = "Jika bukan karena kemampuan psikismu, kami butuh waktu lama untuk menemukannya.",
  ui_story_31290601_21_dialog_content = "Tapi kami masih kehilangan mereka ...",
  ui_story_31290601_22_dialog_content = "Tidak, kami tidak boleh menyerah. Biarkan saya mencoba lagi.",
  ui_story_31290601_23_dialog_content = "...",
  ui_story_31290601_24_dialog_content = "Ada terlalu banyak informasi ...",
  ui_story_31290601_25_dialog_content = "Bisakah kita setidaknya tahu ke arah mana mereka berada?",
  ui_story_31290601_26_dialog_content = "Hewan-hewan di tepi danau tampak gelisah.",
  ui_story_31290601_27_dialog_content = "Mari kita pergi.",
  ui_story_31290601_28_dialog_content = "Saya mungkin bisa mendapatkan lebih banyak informasi jika kita lebih dekat.",
  ui_story_31290601_29_dialog_content = "(Sekitar tiga hari yang lalu, Luke datang ke Colossus untuk menemukan saya.)",
  ui_story_31290601_30_dialog_content = "(Dia ingin saya membantunya menangkap pemburu yang mengejar Rainy Flappers.)",
  ui_story_31290601_31_dialog_content = "(Mereka adalah jenis kupu-kupu yang penjualannya dilarang oleh Persekutuan Umbraton, tetapi masih ada beberapa yang diperdagangkan.)",
  ui_story_31290601_32_dialog_content = "(Penjual sangat cerdas. Bethel mencari tempat mereka beberapa kali, tetapi tidak dapat menemukan apa pun.)",
  ui_story_31290601_33_dialog_content = "(Jadi dia meminta White Flame Mercenaries untuk menangkap para pemburu dan menyelesaikan masalah ini untuk selamanya.)",
  ui_story_31290601_34_dialog_content = "Saya pikir kita menuju ke arah yang benar. Aku bisa merasakan Aurorian.",
  ui_story_31290601_35_dialog_content = "Mereka tidak bergerak sama sekali.",
  ui_story_31290601_36_dialog_content = "Satu... Dua.. Ada tiga.",
  ui_story_31290601_37_dialog_content = "Mereka sedang berbicara.",
  ui_story_31290601_38_dialog_content = "\"Masukkan semuanya ke dalam tas ini! Cepat!\"",
  ui_story_31290601_39_dialog_content = "Tapi aku tidak bisa melihat sisanya.",
  ui_story_31290601_40_dialog_content = "Saya pikir mereka adalah kepompong Rainy Flapper. Mereka harus segera muncul.",
  ui_story_31290601_41_dialog_content = "Tiga dari mereka... Seperti dugaan Bethel.",
  ui_story_31290601_42_dialog_content = "Ada banyak orang yang terlibat dalam penjualan, tetapi perburuan hanya dilakukan oleh beberapa orang.",
  ui_story_31290601_43_dialog_content = "Mari kita mendekat perlahan agar kita tidak memperingatkan mereka.",
  ui_story_31290601_44_dialog_content = "Hutan ini luar biasa panas.",
  ui_story_31290601_45_dialog_content = "Saya sangat berkeringat sehingga hampir seperti baru keluar dari air.",
  ui_story_31290601_46_dialog_content = "Sekarang saya tahu mengapa Anda melepas jubah itu.",
  ui_story_31290601_47_option_content = "Anda terlihat baik, meskipun.",
  ui_story_31290601_48_dialog_content = "Terima kasih atas pujianmu.",
  ui_story_31290601_49_option_content = "Aku belum pernah melihatmu dengan pakaian ini sebelumnya.",
  ui_story_31290601_50_dialog_content = "Saya tidak begitu miskin sehingga saya harus memakai pakaian yang sama setiap hari.",
  ui_story_31290601_51_dialog_content = "Panas akan menghentikan saya jika saya tidak berubah.",
  ui_story_31290601_52_dialog_content = "Aurora dan Caelestites tidak tahan panas.",
  ui_story_31290601_53_dialog_content = "Tapi Rainy Flappers hanya bisa bertahan dalam kondisi ini.",
  ui_story_31290601_54_dialog_content = "Begitu mereka meninggalkan lingkungan, sayap mereka segera mengering, dan mereka tidak akan bisa terbang.",
  ui_story_31290601_55_dialog_content = "Apakah itu berarti mereka mati begitu mereka keluar dari hutan?",
  ui_story_31290601_56_dialog_content = "Itu adalah bagian terburuknya, karena tidak banyak dari mereka untuk memulai.",
  ui_story_31290601_57_dialog_content = "Dan sejumlah besar dari mereka mati selama transportasi dari hutan ke Umbraton.",
  ui_story_31290601_58_dialog_content = "Tapi kehilangan itu tidak serta merta menjadi hal yang buruk bagi para pemburu liar.",
  ui_story_31290601_59_dialog_content = "Karena semakin sedikit jumlahnya, semakin banyak yang bisa mereka dapatkan di pasar gelap.",
  ui_story_31290601_60_dialog_content = "Baik guild maupun saya tidak ingin melihat ini terjadi.",
  ui_story_31290601_61_dialog_content = "Sama seperti semua binatang menakjubkan lainnya, Rainy Flappers harus dijaga.",
  ui_story_31290601_62_dialog_content = "Aku mengerti.",
  ui_story_31290601_63_dialog_content = "Terima kasih, PlayerName.",
  ui_story_31290601_64_dialog_content = "Saya tidak tahu bagaimana harus berterima kasih atas pengertian dan asisten Anda. SAYA...",
  ui_story_31290601_65_dialog_content = "Tunggu, mereka kabur!",
  ui_story_31290601_66_dialog_content = "Pergilah!",
  ui_story_31290601_67_dialog_content = "Mereka berpisah, dan mereka masing-masing memiliki tas.",
  ui_story_31290601_68_dialog_content = "Jika mereka bersungguh-sungguh dengan apa yang mereka katakan sebelumnya...",
  ui_story_31290601_69_dialog_content = "\"Masukkan semuanya ke dalam tas ini! Cepat!\"",
  ui_story_31290601_70_dialog_content = "Hanya satu tas yang memiliki Flappers!",
  ui_story_31290601_71_dialog_content = "Tapi hanya ada kami berdua. Bagaimana kita melakukan ini?",
  ui_story_31290601_72_dialog_content = "gelap...",
  ui_story_31290601_73_dialog_content = "Aku hampir jatuh!",
  ui_story_31290601_74_dialog_content = "Kenapa ada genangan air disini?",
  ui_story_31290601_75_dialog_content = "Ini bukan sekadar genangan air. mereka adalah <color=#FFB400>murung</color>, binatang ajaib lain yang terlihat seperti slime.",
  ui_story_31290601_76_dialog_content = "Aku bisa melihat sisik kupu-kupu pada mereka. Para pemburu pasti sudah pergi lewat sini.",
  ui_story_31290601_77_dialog_content = "Itu berarti mereka muncul!",
  ui_story_31290601_78_dialog_content = "Ini harus menjadi arah yang benar.",
  ui_story_31290601_79_dialog_content = "Jangan buang-buang waktu!",
  ui_story_31290601_80_dialog_content = "(Musuh kali ini lebih sulit untuk dihadapi.)",
  ui_story_31290601_81_dialog_content = "(Mereka tahu di mana kita berada tidak peduli bagaimana kita berputar-putar. Sesuatu sedang terjadi.)",
  ui_story_31290601_82_dialog_content = "(Jadi kami harus berpisah, dan kami tidak tahu siapa yang akan tertangkap.)",
  ui_story_31290601_83_dialog_content = "(Mereka tidak tahu bahwa saya memiliki Flappers, bukan?)",
  ui_story_31290601_84_option_content = "Berhenti!",
  ui_story_31290601_85_dialog_content = "Hah???",
  ui_story_31290601_86_dialog_content = "Bagaimana Anda tahu itu saya? Maksudku, ini adalah kesempatan satu banding tiga...",
  ui_story_31290601_87_dialog_content = "Ada tiga dari Anda, tapi dua dari kami, jadi itu benar-benar dua-dalam-tiga.",
  ui_story_31290601_88_dialog_content = "Kemungkinan ada di pihak kita.",
  ui_story_31290601_89_dialog_content = "Timbangan terus jatuh dari tas Anda, jadi itu berarti Anda harus memiliki Flappers.",
  ui_story_31290601_90_dialog_content = "Dua-dalam-tiga berarti hanya ada satu dari Anda.",
  ui_story_31290601_91_dialog_content = "Dan kau terlihat sangat rapuh. Aku akan mematahkan semua tulangmu!",
  ui_story_31290601_92_dialog_content = "Apakah Anda tidak mendengar saya? Saya mengatakan ada dua dari kami.",
  ui_story_31290601_93_dialog_content = "Apa?",
  ui_story_31290601_94_dialog_content = "Serahkan padaku.",
  ui_story_31290601_95_dialog_content = "Bug! Bug!",
  ui_story_31290601_96_dialog_content = "Aku tidak takut pada mereka! aku tidak af...",
  ui_story_31290601_97_dialog_content = "Diamlah.",
  ui_story_31290601_98_dialog_content = "Apa pemandangan yang indah.",
  ui_story_31290601_99_dialog_content = "(Luke hanya mengeluarkan Flappers di dalam tas.)",
  ui_story_31290601_100_dialog_content = "(Tapi semua kupu-kupu di hutan menari bersama mereka.)",
  ui_story_31290601_101_dialog_content = "Mereka terlihat jauh lebih baik saat melayang di udara.",
  ui_story_31290601_102_dialog_content = "Ya.",
  ui_story_31290601_103_dialog_content = "Para pemburu memasukkannya ke dalam tas, lalu memasukkan masing-masing ke dalam kotak untuk menjaga kecantikannya.",
  ui_story_31290601_104_dialog_content = "Tapi sayap mereka begitu polos dan membosankan saat mereka tidak bergerak.",
  ui_story_31290601_105_dialog_content = "Rainbow hanya muncul ketika mereka mengepakkan sayapnya.",
  ui_story_31290601_106_dialog_content = "Apakah Anda melihatnya?",
  ui_story_31290601_107_dialog_content = "Ya, benar!",
  ui_story_31290601_108_dialog_content = "Aduh, aduh!",
  ui_story_31290601_109_dialog_content = "Saya pikir Anda menarik tali terlalu kencang.",
  ui_story_31290601_110_dialog_content = "Sekarang dia tahu bagaimana perasaan Flappers.",
  ui_story_31290601_111_dialog_content = "Bagaimana dengan dua lainnya?",
  ui_story_31290601_112_dialog_content = "Mereka pasti melarikan diri setelah mengetahui bahwa kami menangkap salah satu dari mereka.",
  ui_story_31290601_113_dialog_content = "Tapi saya tidak berpikir mereka akan menyerah, karena uangnya terlalu bagus.",
  ui_story_31290601_114_dialog_content = "Setelah Anda membuka sesuatu, sisanya menjadi jauh lebih mudah.",
  ui_story_31290601_115_dialog_content = "Jangan lupa bahwa Bethel memiliki seluruh Geng Istvan di belakangnya.",
  ui_story_31290601_116_dialog_content = "Hmm... betul sekali.",
  ui_story_31290601_117_dialog_content = "Itu sangat indah.",
  ui_story_31290601_118_dialog_content = "Namun…",
  ui_story_31290601_119_dialog_content = "...Tetapi?",
  ui_story_31290601_120_dialog_content = "Tapi itu mungkin kesempatan sekali seumur hidup.",
  ui_story_31290601_121_dialog_content = "Jangan khawatir, navigator. Ada cara lain untuk memuji dan mengingat kecantikan mereka.",
  ui_story_31290601_122_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian...</color>",
  ui_story_31290601_123_dialog_content = "(Di sinilah cerita berakhir.)",
  ui_story_31290601_124_dialog_content = "(Setelah mendapatkan bukti nyata, Bethel mengirim orang-orangnya untuk menangkap para penjual.)",
  ui_story_31290601_125_dialog_content = "(Para pemburu yang melarikan diri juga tertangkap.)",
  ui_story_31290601_126_dialog_content = "(Mereka ketakutan ketika melihat dua gurita di rumah mereka.)",
  ui_story_31290601_127_dialog_content = "Siapa kau?",
  ui_story_31290601_128_dialog_content = "Anda disana. Mari kita selesaikan ini dengan.",
  ui_story_31290601_129_dialog_content = "Mengapa Anda membuat semuanya begitu lengket?",
  ui_story_31290601_130_dialog_content = "Oh, ya?",
  ui_story_31290601_131_dialog_content = "Lihat siapa yang berbicara.",
  ui_story_31290601_132_dialog_content = "(Luke tidak berhenti, dan segera memulai pekerjaan lain setelah menyelesaikan yang ini.)",
  ui_story_31290601_133_dialog_content = "(Kami bahkan tidak bisa mengucapkan selamat tinggal dengan benar.)",
  ui_story_31290601_134_dialog_content = "(Tapi saya memang menerima lukisan darinya. Dia melukisnya sendiri.)",
  ui_story_31290601_135_dialog_content = "(Ini adalah lukisan tentang apa yang terjadi hari itu di hutan, dengan Rainy Flappers menari di hutan.)"
}
return config
